function majorityValue(nums: number[]): number {
  const count = new Map<number, number>();
  for (const x of nums) {
    const c = (count.get(x) ?? 0) + 1;
    if (c > nums.length / 2) return x;
    count.set(x, c);
  }
  return nums[0];
}

